ingest.py: chunk and embed
Reads PDF, .txt and .md. Every chunk keeps a location to cite.
def chunks_from_pdf(path):
    reader = PdfReader(path)
    for page_num, page in enumerate(reader.pages, start=1):
        text = " ".join((page.extract_text() or "").split())
        for i in range(0, len(text), CHUNK_CHARS):
            piece = text[i:i + CHUNK_CHARS]
            if len(piece) &gt; 50:
                yield {"source": path.name,
                       "loc": f"p. {page_num}", "text": piece}

# .txt / .md: split at headings and blank lines, tag "lines 12-30"
